public async Task<List<OrderDto>> GetRecentOrdersAsync()
{
    // Query 1: SELECT * FROM Orders
    var orders = await _context.Orders
        .Where(o => o.CreatedAt > DateTime.UtcNow.AddDays(-30))
        .ToListAsync();

    // Query 2..N+1: SELECT * FROM Customers WHERE Id = @p0
    var result = new List<OrderDto>();
    foreach (var order in orders)
    {
        result.Add(new OrderDto
        {
            Id = order.Id,
            CustomerName = order.Customer.Name // Lazy load triggers query
        });
    }

    return result;
}

public async Task<List<OrderDto>> GetRecentOrdersAsync()
{
    var orders = await _context.Orders
        .Include(o => o.Customer)
        .Where(o => o.CreatedAt > DateTime.UtcNow.AddDays(-30))
        .ToListAsync();

    // No additional queries: Customer is already loaded
    return orders.Select(o => new OrderDto
    {
        Id = o.Id,
        CustomerName = o.Customer.Name
    }).ToList();
}

